   !> DPCM (gaussian charges): linear response of the v, vn gradient
   !>
   !> - Directions of v, vn only; the state is not changed
   !> - Needs dpcm_complex_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_complex_mf_response(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm
      type(dpcm_complex_state), intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      complex(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      complex(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[dpcm_complex_mf_response] call dpcm_complex_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_complex_mf_response] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_complex_mf_response] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_complex_mf_response] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_complex_mf_response] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call dpcm_complex_mf_response_one(state, dv(:, blk), dvn(:, blk), hvp_v(:, blk), &
                                           hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine dpcm_complex_mf_response

   !> One direction of dpcm_complex_mf_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_complex_mf_response_one(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm
      type(dpcm_complex_state), target, intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:)
      !> Direction for vn
      complex(wp), contiguous, intent(in) :: dvn(:)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:)
      !> Hessian times direction, vn block
      complex(wp), contiguous, intent(out) :: hvp_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[dpcm_complex_mf_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt])) then
         call fatal_error(error, "[dpcm_complex_mf_response_one] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[dpcm_complex_mf_response_one] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_complex_mf_response_one] hvp_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_complex_mf_response_one] allocation failed")
         return
      end if

      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%xi => state%xi
      state%op4%a => state%a
      tmp1 = state%a*dvn
      tmp2 = 0.0_wp
      call state%solver%solve_complex(state%op4, .false., tmp1, tmp2, error)
      if (allocated(error)) return
      hvp_v = state%cx_s12*tmp2
      tmp3 = 0.0_wp
      call state%solver%solve_complex(state%op4, .true., dv, tmp3, error)
      if (allocated(error)) return
      tmp4 = state%cx_s12*tmp3
      hvp_vn = tmp4*state%a
   end subroutine dpcm_complex_mf_response_one

   !> DPCM (gaussian charges): energy derivatives with respect to the solvent parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs dpcm_complex_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_complex_mf_param_weights(state, grad_eps, error)
      !> State of dpcm
      type(dpcm_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to eps
      complex(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp), allocatable :: tmp1(:), tmp4(:), tmp5(:)
      complex(wp) :: tmp2, tmp3, tmp6, tmp7, tmp8, tmp9, tmp10

      stat = 0
      npt = state%npt
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[dpcm_complex_mf_param_weights] call dpcm_complex_solve first")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_complex_mf_param_weights] allocation failed")
         return
      end if

      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%xi => state%xi
      state%op4%a => state%a
      tmp1 = 0.5_wp*state%cx_v
      tmp2 = sum(tmp1*state%cx_s11)
      tmp3 = (-0.5_wp)*state%cx_s2
      tmp4 = tmp3*state%cx_s13
      tmp5 = state%a*state%cx_s15
      tmp6 = sum(tmp4*tmp5)
      tmp7 = -tmp6
      tmp8 = tmp2 + tmp7
      tmp9 = state%cx_s1**(-2)
      tmp10 = tmp8*tmp9
      grad_eps = 2.0_wp*tmp10
   end subroutine dpcm_complex_mf_param_weights

   !> Apply operator 1 or its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine dpcm_op1_apply(self, trans, x, y)
      !> Operator
      class(dpcm_op1), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         block
            real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:)

            allocate (tmp1(self%npt))
            allocate (tmp2(self%npt))
            allocate (tmp3(self%npt))
            allocate (tmp4(self%npt))
            tmp1 = 6.283185307179586_wp*x
            tmp2 = self%a*x
            call gemv(self%c2, tmp2, tmp3)
            tmp4 = self%c1*tmp3
            y = tmp1 + tmp4
         end block
      else
         block
            real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:)

            allocate (tmp1(self%npt))
            allocate (tmp2(self%npt))
            allocate (tmp3(self%npt))
            allocate (tmp4(self%npt))
            tmp1 = 6.283185307179586_wp*x
            call gemv(self%c2, x, tmp2, trans="t")
            tmp3 = self%a*tmp2
            tmp4 = self%c1*tmp3
            y = tmp1 + tmp4
         end block
      end if
   end subroutine dpcm_op1_apply

   !> Form operator 1 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine dpcm_op1_assemble(self, a, error)
      !> Operator
      class(dpcm_op1), intent(in) :: self
      !> Dense operator matrix
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :), tmp3(:, :), tmp4(:, :), tmp5(:, :)
      integer :: i

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp2(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp3(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp4(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp5(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_op1_assemble] allocation failed")
